/** Dhikr (remembrance) category */
interface DhikrCategory {
    id: number;
    name: string;
}
/** Single dhikr item */
interface DhikrItem {
    id: number;
    categoryId: number;
    arabic: string;
    kurdish: string;
    count: number;
}
/** Dhikr dataset */
interface DhikrData {
    categories: DhikrCategory[];
    items: DhikrItem[];
}
/** Name of Allah (Asma ul Husna) */
interface NameOfAllah {
    id: number;
    arabic: string;
    kurdish: string;
    english: string;
}
/** Coordinates */
interface Coordinates {
    lat: number;
    lng: number;
}
/** Qibla calculation result */
interface QiblaResult {
    direction: number;
    kaaba: Coordinates;
    from: Coordinates;
}

